def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    prev_bids = []
    desperate_prev = []
    rich_aggressive = []

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                    desperate_prev.append(float(bid))
                if opp.get('budget', 0) >= 120 and float(bid) >= DAILY_SALARY * 1.3:
                    rich_aggressive.append(float(bid))

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 12.0))

    slots = int(supply // WATER_REQ)
    if slots < 1:
        slots = 1

    n_alive = len(alive) + 1
    scarcity = n_alive - slots

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    desperate_top = max(desperate_prev) if desperate_prev else 0.0
    aggro_top = max(rich_aggressive) if rich_aggressive else 0.0

    urgent = hp <= 3 or no_water >= 1
    very_urgent = hp <= 2 or no_water >= 2

    if very_urgent:
        bid = max(DAILY_SALARY * 1.25, highest_prev + 3.0, desperate_top + 2.0)
    elif scarcity >= 3:
        if urgent:
            bid = max(DAILY_SALARY * 1.1, highest_prev + 2.0)
        else:
            bid = max(DAILY_SALARY * 0.88, avg_prev + 2.0)
    elif scarcity == 2:
        if urgent:
            bid = max(DAILY_SALARY * 0.98, highest_prev + 1.5)
        else:
            bid = max(DAILY_SALARY * 0.72, avg_prev * 0.92)
    elif scarcity == 1:
        if urgent:
            bid = max(DAILY_SALARY * 0.85, avg_prev * 0.8 + 3.0)
        else:
            bid = DAILY_SALARY * 0.42
    else:
        if urgent:
            bid = DAILY_SALARY * 0.55
        else:
            bid = DAILY_SALARY * 0.18

    if aggro_top > 0 and scarcity >= 2 and not urgent:
        bid = min(bid, DAILY_SALARY * 0.52)

    if day >= 8 and hp >= 5 and budget < DAILY_SALARY * 2:
        bid = min(bid, DAILY_SALARY * 0.45)

    min_safe = 0.0
    if urgent:
        min_safe = 18.0
    elif scarcity >= 2:
        min_safe = 24.0
    else:
        min_safe = 10.0

    bid = max(bid, min_safe)
    bid = min(bid, budget)
    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]

    avg_opp = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 60.0

    if my_status['hp'] < 4:
        return min(my_status['budget'], DAILY_SALARY * 0.8)

    bid = avg_opp * 1.05
    if day_context['supply'] < WATER_REQ * 1.2:
        bid = max(bid, 80.0)

    return min(my_status['budget'], bid)
